String tr(BuildContext c,String value)=>Localizations.localeOf(c).languageCode=='bn'?_bn[value]??value:value;
class CopyText extends StatelessWidget {
 final String data;final TextStyle? style;final int? maxLines;final TextOverflow? overflow;final TextAlign? textAlign;
 const CopyText(this.data,{super.key,this.style,this.maxLines,this.overflow,this.textAlign});
 @override Widget build(BuildContext c)=>Text(tr(c,data),style:style,maxLines:maxLines,overflow:overflow,textAlign:textAlign);
}
